import { z } from "zod";
import { Finding, Theme } from "./finding";
import { Requirement } from "./requirement";
import { Source, SourceRecord } from "./source";

/**
 * The single envelope that flows along every workflow edge (n8n-style: one input, one output).
 * A node reads the keys it `consumes` and returns the envelope with the keys it `produces` updated.
 */
export const DATA_KEYS = ["sources", "records", "findings", "themes", "requirements"] as const;
export const DataKey = z.enum(DATA_KEYS);
export type DataKey = z.infer<typeof DataKey>;

export const PipelineData = z.object({
  sources: z.array(Source),
  records: z.array(SourceRecord),
  findings: z.array(Finding),
  themes: z.array(Theme),
  requirements: z.array(Requirement),
});
export type PipelineData = z.infer<typeof PipelineData>;

export function emptyPipelineData(): PipelineData {
  return { sources: [], records: [], findings: [], themes: [], requirements: [] };
}

function mergeById<T extends { id: string }>(lists: T[][]): T[] {
  const byId = new Map<string, T>();
  for (const list of lists) for (const item of list) byId.set(item.id, item);
  return [...byId.values()];
}

/**
 * How the engine combines several incoming edges into one node input:
 * concatenate per key and de-duplicate by `id`; a later input wins (order = edge order),
 * first-seen position is kept so output order stays stable.
 */
export function mergePipelineData(...parts: PipelineData[]): PipelineData {
  return {
    sources: mergeById(parts.map((p) => p.sources)),
    records: mergeById(parts.map((p) => p.records)),
    findings: mergeById(parts.map((p) => p.findings)),
    themes: mergeById(parts.map((p) => p.themes)),
    requirements: mergeById(parts.map((p) => p.requirements)),
  };
}

export function countPipelineData(data: PipelineData): Record<DataKey, number> {
  return {
    sources: data.sources.length,
    records: data.records.length,
    findings: data.findings.length,
    themes: data.themes.length,
    requirements: data.requirements.length,
  };
}
import { z } from "zod";

/**
 * Explainable prioritization: every factor is 0–5 where HIGHER always means "more worth doing".
 * total = 100 × Σ(weight × value) / (5 × Σ weight)   →   0–100
 * Weights and priority thresholds live in Settings.scoring and are recorded with each score.
 */
export const ScoreFactor = z.enum([
  "customer_impact", // how strongly and how many customers are affected
  "evidence_strength", // number, independence and reliability of supporting sources
  "competitive_gap", // competitors offer it / do it better
  "trend_momentum", // expected relevance when the successor launches (3–5 years)
  "brand_fit", // fit with BMW brand promise (premium, driving pleasure, …)
  "ease", // inverse of rough effort/cost — the only business factor allowed by the briefing
]);
export type ScoreFactor = z.infer<typeof ScoreFactor>;

export const SCORE_FACTOR_LABELS: Record<ScoreFactor, string> = {
  customer_impact: "Customer impact",
  evidence_strength: "Evidence strength",
  competitive_gap: "Competitive gap",
  trend_momentum: "Trend momentum",
  brand_fit: "Brand fit",
  ease: "Ease of delivery (inverse effort)",
};

/** MoSCoW priority bands. */
export const Priority = z.enum(["must", "should", "could", "wont"]);
export type Priority = z.infer<typeof Priority>;

export const ScoreWeights = z.record(ScoreFactor, z.number().min(0).max(10));
export type ScoreWeights = z.infer<typeof ScoreWeights>;

/** Minimum total score for each band; below `could` → "wont". */
export const PriorityThresholds = z
  .object({
    must: z.number().min(0).max(100),
    should: z.number().min(0).max(100),
    could: z.number().min(0).max(100),
  })
  .refine((t) => t.must > t.should && t.should > t.could, {
    message: "Thresholds must satisfy must > should > could",
  });
export type PriorityThresholds = z.infer<typeof PriorityThresholds>;

export const FactorScore = z.object({
  value: z.number().min(0).max(5),
  weight: z.number().min(0).max(10), // weight at scoring time (snapshot of Settings)
  note: z.string().min(1), // one-line justification, shown to the PM
});
export type FactorScore = z.infer<typeof FactorScore>;

export const ScoreBreakdown = z.object({
  factors: z.record(ScoreFactor, FactorScore),
  total: z.number().min(0).max(100),
  suggestedPriority: Priority, // what the score says; Requirement.priority may be overridden by the PM
  method: z.string().min(1), // versioned, e.g. "weighted-sum@1"
  scoredAt: z.iso.datetime(),
});
export type ScoreBreakdown = z.infer<typeof ScoreBreakdown>;

/** The documented formula: 100 × Σ(weight × value) / (5 × Σ weight), rounded to one decimal. */
export function weightedTotal(
  values: Record<ScoreFactor, number>,
  weights: Record<ScoreFactor, number>,
): number {
  let num = 0;
  let den = 0;
  for (const f of ScoreFactor.options) {
    const v = values[f];
    const w = weights[f];
    if (!(v >= 0 && v <= 5)) throw new RangeError(`Factor ${f} must be within 0–5, got ${v}`);
    if (!(w >= 0)) throw new RangeError(`Weight for ${f} must be ≥ 0, got ${w}`);
    num += w * v;
    den += 5 * w;
  }
  if (den === 0) throw new RangeError("At least one score weight must be > 0");
  return Math.round((1000 * num) / den) / 10;
}

export function priorityForScore(total: number, t: PriorityThresholds): Priority {
  if (total >= t.must) return "must";
  if (total >= t.should) return "should";
  if (total >= t.could) return "could";
  return "wont";
}
import { z } from "zod";
import { ProductScope } from "./scope";
import { PriorityThresholds, ScoreWeights } from "./scoring";

/** "mock" returns canned, schema-valid output so the app runs offline and in tests. */
export const LlmProvider = z.enum(["anthropic", "mock"]);
export type LlmProvider = z.infer<typeof LlmProvider>;

export const ResearchProvider = z.enum(["anthropic_web_search", "tavily", "off"]);
export type ResearchProvider = z.infer<typeof ResearchProvider>;

export const ThemePreference = z.enum(["system", "light", "dark"]);
export type ThemePreference = z.infer<typeof ThemePreference>;

/** Language of AI-written text (findings, requirements). The UI itself is English. */
export const OutputLanguage = z.enum(["en", "de"]);
export type OutputLanguage = z.infer<typeof OutputLanguage>;

export const MemberRole = z.enum(["owner", "editor", "viewer"]);
export type MemberRole = z.infer<typeof MemberRole>;

/** A teammate. "invited" until they join; sending invitations needs the sync backend. */
export const TeamMember = z.object({
  id: z.string().min(1),
  name: z.string().trim().min(1).max(80),
  email: z.email(),
  role: MemberRole,
  status: z.enum(["active", "invited"]),
});
export type TeamMember = z.infer<typeof TeamMember>;

/** Where shared workflows and decisions live: only this machine, a shared folder, or a Git repo. */
export const SharingMode = z.enum(["local", "shared_folder", "git"]);
export type SharingMode = z.infer<typeof SharingMode>;

/**
 * Everything the Settings page edits. API keys are NOT settings — they are stored encrypted in the
 * OS keychain by the main process (`settings.setSecret`); the UI only learns whether one is configured.
 */
export const Settings = z.object({
  app: z.object({
    theme: ThemePreference,
    snapToGrid: z.boolean(), // workplace
    showMinimap: z.boolean(), // workplace
    confirmBeforeDelete: z.boolean(),
  }),
  llm: z.object({
    provider: LlmProvider,
    model: z.string().min(1), // quality tier: clustering, derivation, challenge answers
    fastModel: z.string().min(1), // bulk tier: per-record signal extraction
    temperature: z.number().min(0).max(1),
    outputLanguage: OutputLanguage,
  }),
  research: z.object({
    provider: ResearchProvider,
    maxResultsPerQuery: z.number().int().min(1).max(50),
    allowedDomains: z.array(z.string()), // empty = any
    blockedDomains: z.array(z.string()),
  }),
  scoring: z.object({
    weights: ScoreWeights,
    thresholds: PriorityThresholds,
  }),
  review: z.object({
    // The prototype has no login: this identity is the human actor in the audit trail.
    reviewer: z.object({
      userId: z.string().min(1),
      name: z.string().min(1),
      role: z.string().min(1),
    }),
  }),
  /** The global vehicle and market. Blocks set to "From Settings" use these. */
  defaultScope: ProductScope,
  collaboration: z.object({
    members: z
      .array(TeamMember)
      .refine(
        (ms) => new Set(ms.map((m) => m.email.toLowerCase())).size === ms.length,
        "This person is already on the team",
      ),
    sharing: SharingMode,
    sharedLocation: z.string().max(500), // folder path or Git URL; empty while sharing is "local"
    notifyOnReview: z.boolean(), // tell teammates when a HIL block waits for them
    requireSecondApproval: z.boolean(), // four-eyes rule for approving requirements
  }),
});
export type Settings = z.infer<typeof Settings>;

