+function validateNote(note: string, entry: PromptItem, factor: ScoreFactor): void {
+  if (/^(Assumption:|MOCK assumption:)/i.test(note)) return;
+  const match = /^Evidence:\s*(src_\S+|rec_\S+)\s*\|\s*("(?:[^"\\]|\\.)*")\s*\|\s*\S.+$/i.exec(note);
+  if (!match) throw new Error(`Provisional ${entry.id} factor ${factor} note must identify Assumption: or Evidence: ID | "verbatim excerpt" | judgement`);
+  const id = match[1]!;
+  let excerpt: string;
+  try { excerpt = JSON.parse(match[2]!) as string; }
+  catch { throw new Error(`Provisional ${entry.id} factor ${factor} evidence quote must be JSON-quoted`); }
+  const records = [...entry.context.records, ...(entry.layer === "records" ? [entry.item as PipelineData["records"][number]] : [])];
+  const findings = [...entry.context.findings, ...(entry.layer === "findings" ? [entry.item as PipelineData["findings"][number]] : [])];
