+    ...findings.flatMap((finding) => finding.evidence.filter((ref) => ref.sourceId === id || ref.recordId === id).map((ref) => ref.excerpt)),
+  ];
+  if (!excerpt.trim() || !texts.some((text) => text.includes(excerpt))) {
